QB("asbab",4,0,[[2,2,"قوله - عز وجل - {وآتوا اليتامى أموالهم} الآية {2} .\nقال مقاتل والكلبي: نزلت في رجل من غطفان كان عنده مالك كثير لابن أخ له يتيم، فلما بلغ اليتيم طلب المال، فمنعه عمه، فترافعا إلى النبي - صلى الله عليه وسلم - فنزلت هذه الآية، فلما سمعها العم قال: أطعنا الله وأطعنا الرسول، نعوذ بالله من الحوب الكبير، فدفع إليه ماله، فقال النبي - صلى الله عليه وسلم - \"من يوق شح نفسه ورجع به هكذا فإنه يحل داره\"، يعني جنته، فلما قبض الفتى ماله أنفقه في سبيل الله تعالى، فقال النبي - صلى الله عليه وسلم - \"ثبت الأجر وبقي الوزر\" فقالوا: يا رسول الله، قد عرفنا أنه ثبت الأجر، فكيف بقي الوزر وهو ينفق في سبيل الله؟ فقال: \"ثبت الأجر للغلام وبقي الوزر على والده\"."],[3,3,"قوله تعالى: {وإن خفتم ألا تقسطوا في اليتامى} الآية {3} .\nأخبرنا أبو بكر التميمي، أخبرنا عبد الله بن محمد قال: حدثنا أبو يحيى قال: حدثنا سهل بن عثمان قال: حدثنا يحيى بن أبي زائدة، عن هشام بن عروة، عن أبيه، عن عائشة في قوله تعالى: {وإن خفتم ألا تقسطوا} الآية. قالت: أنزلت هذه في الرجل يكون له اليتيمة وهو وليها ولها مال وليس لها أحد يخاصم دونها،\nفلا ينكحها حبا لمالها، ويضربها ويسيء صحبتها، فقال الله تعالى: {وإن خفتم ألا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء} يقول: ما أحللت لكم ودع هذه. رواه مسلم عن أبي كريب عن أبي\nأسامة، عن هشام.\n(1) - وقال سعيد بن جبير وقتادة والربيع والضحاك والسدي: كانوا يتحرجون عن أموال اليتامى ويترخصون في النساء، ويتزوجون ما شاءوا، فربما عدلوا وربما لم يعدلوا، فلما سألوا عن اليتامى، فنزلت آية اليتامى: {وآتوا اليتامى أموالهم} الآية، أنزل الله تعالى أيضا: {وإن خفتم ألا تقسطوا في اليتامى} الآية. يقول: كما خفتم ألا تقسطوا في اليتامى، فكذلك فخافوا في النساء أن لا تعدلوا فيهن، فلا تزوجوا أكثر مما يمكنكم القيام بحقهن، لأن النساء كاليتامى في الضعف والعجز، وهذا قول ابن عباس في رواية الوالبي."],[6,6,"قوله تعالى: {وابتلوا اليتامى} الآية {6} .\nنزلت في ثابت بن رفاعة وفي عمه، وذلك أن رفاعة توفي وترك ابنه ثابتا وهو صغير، فأتى عم ثابت إلى النبي - صلى الله عليه وسلم - فقال: إن ابن أخي يتيم في حجري، فما يحل لي من ماله، ومتى أدفع إليه ماله؟ فأنزل الله تعالى هذه الآية."],[7,7,"قوله تعالى: {للرجال نصيب مما ترك الوالدان والأقربون} الآية {7} .\nقال المفسرون: إن أوس بن ثابت الأنصاري توفي وترك امرأة يقال\nلها: أم كجة وثلاث بنات له منها، فقام رجلان: هما ابنا عم الميت ووصياه، يقال لهما: سويد وعرفجة،\nفأخذا ماله ولم يعطيا امرأته شيئا ولا بناته، وكانوا في الجاهلية لا يورثون النساء ولا الصغير وإن كان ذكرا، إنما يورثون الرجال الكبار، وكانوا يقولون: لا يعطى إلا من قاتل على ظهور الخيل وحاز الغنيمة، فجاءت أم كجة إلى رسول الله - صلى الله عليه وسلم - فقالت: يا رسول الله: إن أوس بن ثابت مات وترك علي بنات وأنا امرأته وليس عندي ما أنفق عليهن، وقد ترك أبوهن مالا حسنا وهو عند سويد وعرفجة لم يعطياني ولا بناته من المال شيئا وهن في حجري، ولا يطعماني ولا يسقياني ولا يرفعان لهن رأسا. فدعاهما رسول الله - صلى الله عليه وسلم - فقالا: يا رسول الله ولدها لا يركب فرسا ولا يحمل كلا ولا ينكي عدوا، فقال رسول الله - صلى الله عليه وسلم - \"انصرفوا حتى أنظر ما يحدث الله لي فيهن\"، فانصرفوا، فأنزل الله تعالى هذه الآية."],[10,10,"قوله تعالى: {إن الذين يأكلون أموال اليتامى ظلما} الآية {10} .\nقال مقاتل بن حيان: نزلت في رجل من غطفان يقال له: مرثد بن زيد ولي مال ابن أخيه وهو يتيم صغير، فأكله، فأنزل الله فيه هذه الآية."],[11,11,"قوله تعالى: {يوصيكم الله في أولادكم} الآية {11} .\nأخبرنا أحمد بن محمد بن أحمد بن جعفر قال: أخبرنا الحسن بن أحمد المخلدي قال: أخبرنا المؤمل بن الحسن بن عيسى قال: حدثنا الحسن بن محمد بن الصباح قال: حدثنا\nحجاج، عن ابن جريج قال: أخبرني ابن المنكدر، عن جابر\nقال: عادني رسول الله - صلى الله عليه وسلم - وأبو بكر في بني سلمة يمشيان، فوجدني لا أعقل، فدعا بماء فتوضأ، ثم رش علي منه فأفقت فقلت: كيف أصنع في مالي يا رسول الله؟ فنزلت: {يوصيكم الله في أولادكم} الآية. رواه البخاري عن إبراهيم بن موسى، عن هشام، ورواه مسلم عن محمد بن حاتم، عن حجاج، كلاهما عن ابن جريج.\n(1) - أخبرنا أبو منصور محمد بن محمد المنصوري قال: أخبرنا علي بن عمر بن مهدي قال: حدثنا يحيى بن صاعد قال: حدثنا أحمد بن المقدام\nقال: حدثنا بشر بن المفضل قال: حدثنا عبد الله بن محمد بن عقيل، عن جابر بن عبد الله قال: جاءت امرأة إلى رسول الله - صلى الله عليه وسلم - بابنتين لها، فقالت: يا رسول الله هاتان بنتا ثابت بن قيس، أو قالت سعد بن الربيع، قتل معك يوم أحد، وقد استفاء عمهما مالهما وميراثهما، فلم يدع لهما مالا إلا أخذه، فما ترى يا رسول الله؟ فوالله ما ينكحان أبدا إلا ولهما مال، فقال: \"يقضي الله في ذلك، فنزلت سورة النساء وفيها: {يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين} إلى آخر الآية، فقال لي رسول الله - صلى الله عليه وسلم - \"ادع لي المرأة وصاحبها، فقال لعمهما: أعطهما الثلثين، وأعط أمهما الثمن، وما بقي فلك\"."],[19,19,"قوله تعالى: {يا أيها الذين آمنوا لا يحل لكم أن ترثوا النساء كرها} الآية {19} .\nأخبرنا أبو بكر الأصفهاني. قال: حدثنا عبد الله بن محمد الأصفهاني قال: حدثنا أبو يحيى قال: حدثنا سهل بن عثمان قال: حدثنا أسباط بن محمد، عن الشيباني، عن عكرمة، عن ابن عباس - قال أبو إسحاق الشيباني: وذكره عطاء بن الحسين السوائي، ولا أظنه إلا ذكره عن ابن عباس - في هذه الآية: {يا أيها الذين آمنوا لا يحل لكم أن ترثوا النساء كرها} قال: كانوا إذا مات الرجل كان أولياؤه أحق بامرأته إن شاء بعضهم\nتزوجها، وإن شاءوا زوجوها، وإن شاءوا لم يزوجوها، وهم أحق بها من أهلها، فنزلت هذه الآية في ذلك. رواه البخاري في التفسير، عن محمد بن مقاتل. ورواه في كتاب الإكراه عن حسين بن منصور كلاهما عن أسباط.\n(1) - قال المفسرون: كان أهل المدينة في الجاهلية وفي أول الإسلام، إذا مات الرجل وله امرأة جاء ابنه من غيرها أو قريبه من عصبته فألقى ثوبه على تلك المرأة، فصار أحق بها من نفسها ومن غيره، فإن شاء أن يتزوجها بغير صداق، إلا الصداق الذي أصدقها الميت، وإن شاء زوجها غيره وأخذ صداقها ولم يعطها شيئا، وإن شاء عضلها وضارها لتفتدي منه بما ورثت من الميت، أو تموت هي فيرثها، فتوفي أبو قيس بن الأسلت الأنصاري وترك امرأته كبيشة بنت معن الأنصارية، فقام ابن له من غيرها يقال له: حصن، وقال مقاتل:\nاسمه قيس بن أبي قيس، فطرح ثوبه عليها، فورث نكاحها ثم تركها، فلم يقربها ولم ينقق عليها يضارها لتفتدي منه بمالها، فأتت كبيشة إلى رسول الله - صلى الله عليه وسلم - فقالت: يا رسول الله إن أبا قيس توفي وورث ابنه نكاحي وقد أضر بي وطول علي، فلا هو ينقق علي، ولا يدخل بي، ولا هو يخلي سبيلي، فقال لها رسول الله - صلى الله عليه وسلم - \"اقعدي في بيتك حتى يأتي فيك أمر الله\" قال: فانصرفت وسمعت بذلك النساء في المدينة، فأتين رسول الله - صلى الله عليه وسلم - وقلن: ما نحن إلا كهيأة كبيشة غير أنه لم ينكحنا الأبناء ونكحنا بنو العم، فأنزل الله تعالى هذه الآية."],[22,22,"قوله تعالى: {ولا تنكحوا ما نكح آباؤكم من النساء} الآية {22} .\nنزلت في حصن ابن أبي قيس تزوج امرأة أبيه: كبيشة بنت معن، وفي الأسود بن خلف تزوج امرأة أبيه، وصفوان بن أمية بن خلف تزوج امرأة أبيه: فاختة بنت الأسود بن المطلب، وفي منظور بن زبان تزوج امرأة أبيه: مليكة بنت خارجة.\n(1) - وقال أشعث بن سوار: توفي أبو قيس وكان من صالحي الأنصار، فخطب ابنه قيس امرأة أبيه، فقالت: إني أعدك ولدا، ولكني آتي رسول الله - صلى الله عليه وسلم - أستأمره، فأتته فأخبرته، فأنزل الله تعالى هذه الآية."],[24,24,"قوله تعالى: {والمحصنات من النساء إلا ما ملكت أيمانكم} .\nأخبرنا محمد بن عبد الرحمن البناني قال: أخبرنا محمد بن أحمد بن حمدان قال: أخبرنا أبو يعلى قال: أخبرنا عمرو الناقد قال: حدثنا أبو أحمد الزبيري قال: حدثنا سفيان، عن عثمان البتي، عن أبي الخليل، عن أبي سعيد الخدري قال: أصبنا سبايا يوم أوطاس لهن أزواج، فكرهنا أن نقع عليهن، فسألنا النبي عليه الصلاة والسلام فنزلت: {والمحصنات من النساء إلا ما ملكت أيمانكم} فاستحللناهن.\n(3) - أخبرنا أحمد بن محمد بن أحمد بن الحارث قال: أخبرنا\nعبد الله بن محمد بن جعفر قال: حدثنا أبو يحيى قال: حدثنا سهل بن عثمان.\nأخبرنا عبد الرحيم، عن أشعث بن سوار، عن عثمان البتي، عن أبي الخليل، عن أبي سعيد قال. لما سبا رسول الله - صلى الله عليه وسلم - أهل أوطاس قلنا: يا نبي الله كيف نقع على نساء قد عرفنا أنسابهن وأزواجهن؟ فنزلت هذه الآية {والمحصنات من النساء إلا ما ملكت أيمانكم}\n(1) - أخبرنا أبو بكر محمد بن إبراهيم الفارسي، أخبرنا محمد بن عيسى بن عمرويه، حدثنا إبراهيم بن محمد بن سفيان، حدثنا مسلم بن الحجاج، حدثني عبيد الله بن عمر\nالقواريري، حدثنا يزيد بن زريع، عن سعيد بن أبي عروبة، عن قتادة عن أبي صالح أبي الخيل، عن أبي علقمة الهاشمي.\nعن أبي سعيد الخدري: أن رسول الله - صلى الله عليه وسلم - يوم حنين بعث جيشا إلى أوطاس ولقي عدوا فقاتلوهم، فظهروا عليهم وأصابوا لهم سبايا، وكان ناس من أصحاب رسول الله - صلى الله عليه وسلم - تحرجوا من غشيانهن من أجل أزواجهن من المشركين، فأنزل الله في ذلك: {والمحصنات من النساء إلا ما ملكت أيمانكم}"],[32,32,"قوله تعالى: {ولا تتمنوا ما فضل الله به بعضكم على بعض} {32} .\nأخبرنا إسماعيل ابن أبي القاسم الصوفي، أخبرنا إسماعيل بن نجيد، حدثنا\nجعفر بن محمد بن سوار، أخبرنا قتيبة، حدثنا سفيان بن عيينة، عن ابن أبي نجيح، عن مجاهد قال: قالت أم سلمة: يا رسول الله تغزو الرجال ولا نغزو، وإنما لنا نصف الميراث فأنزل الله تعالى: {ولا تتمنوا ما فضل الله به بعضكم على بعض}\n(1) - أخبرنا محمد بن عبد العزيز، أن محمد بن الحسين أخبرهم عن محمد بن يحيى بن يزيد، أخبرنا إسحاق بن إبراهيم، أخبرنا عتاب بن بشير، عن خصيف، عن عكرمة: أن النساء سألن الجهاد، فقلن: وددنا أن الله جعل لنا الغزو فنصيب من الأجر ما يصيب الرجال، فأنزل الله تعالى: {ولا تتمنوا ما فضل الله به بعضكم على بعض}\n(2) - وقال قتادة والسدي: لما نزل قوله: {للذكر مثل حظ الأنثيين} قال الرجال: إنا لنرجو أن نفضل على النساء بحسناتنا في الآخرة كما فضلنا عليهن في الميراث فيكون أجرنا على الضعف من أجر النساء، وقالت النساء: إنا لنرجو أن يكون الوزر علينا نصف ما على الرجال في الآخرة كما لنا الميراث على النصف من نصيبهم في الدنيا، فأنزل الله تعالى: {ولا تتمنوا ما فضل الله به بعضكم على بعض}"],[33,33,"قوله تعالى: {ولكل جعلنا موالي} الآية {33} .\nأخبرنا أبو عبد الله محمد بن عبد الله الفارسي قال: حدثنا محمد بن عبد الله بن حمويه الهروي قال: أخبرنا علي بن محمد الخزاعي قال: حدثنا أبو اليمان الحكم بن نافع قال: أخبرني شعيب بن أبي حمزة عن الزهري قال: قال سعيد بن المسيب: نزلت هذه الآية: {ولكل جعلنا موالي مما ترك الوالدان والأقربون} في الذين كانوا يتبنون رجالا غير أبنائهم ويورثونهم، فأنزل الله تعالى فيهم: أن يجعل لهم نصيب في الوصية ورد الله تعالى الميراث إلى الموالي من ذوي الرحم والعصبة، وأبى أن يجعل للمدعين ميراث من ادعاهم ويتبناهم، ولكن جعل لهم نصيبا في الوصية."],[34,34,"قوله تعالى: {الرجال قوامون على النساء} الآية {34} .\nقال مقاتل: نزلت هذه الآية في سعد بن الربيع وكان من النقباء، وامرأته حبيبة بنت زيد بن أبي زهير، وهما من الأنصار، وذلك أنها نشزت عليه فلطمها، فانطلق أبوها معها\nإلى النبي - صلى الله عليه وسلم - فقال: أفرشته كريمتي فلطمها. فقال النبي - صلى الله عليه وسلم - \"لتقتص من زوجها\"، وانصرفت مع أبيها لتقتص منه، فقال النبي - صلى الله عليه وسلم - \"ارجعوا، هذا جبريل عليه السلام أتاني\"، وأنزل الله تعالى هذه الآية، فقال رسول الله - صلى الله عليه وسلم - \"أردنا أمرا وأراد الله أمرا، والذي أراد الله خير\"، ورفع القصاص.\n(2) - أخبرنا سعيد بن محمد بن أحمد الزاهد قال: أخبرنا زاهر بن أحمد\nقال: أخبرنا أحمد بن الحسين بن الجنيد قال: حدثنا زياد بن أيوب قال: حدثنا هشيم قال: حدثنا يونس، عن الحسن: أن رجلا لطم امرأته، فخاصمته إلى النبي - صلى الله عليه وسلم - فجاء معها أهلها فقالوا: يا رسول الله إن فلانا لطم صاحبتنا، فجعل رسول الله - صلى الله عليه وسلم - يقول: \"القصاص القصاص، ولا يقضي قضاء\"، فنزلت هذه الآية: {الرجال قوامون على النساء} قال النبي - صلى الله عليه وسلم - \"أردنا أمرا وأراد الله غيره\". أخبرنا أبو بكر الحارثي قال: أخبرنا أبو الشيخ الحافظ قال: حدثنا أبو يحيى الرازي قال: حدثنا سهل العسكري قال: حدثنا علي بن هاشم، عن إسماعيل، عن الحسن قال: لما نزلت آية القصاص بين المسلمين لطم رجل امرأته، فانطلقت إلى النبي - صلى الله عليه وسلم - فقالت: إن زوجي لطمني فالقصاص، قال: \"القصاص\"، فبينا هو كذلك أنزل الله تعالى: {الرجال قوامون على النساء بما فضل الله بعضهم على بعض} فقال النبي - صلى الله عليه وسلم - \"أردنا أمرا فأبى الله تعالى إلا غيره، خذ أيها الرجل بيد امرأتك\"."],[37,37,"قوله تعالى: {الذين يبخلون ويأمرون الناس بالبخل} {37} .\nقال أكثر المفسرين: نزلت في اليهود حين كتموا صفة محمد - صلى الله عليه وسلم - ولم يبينوها للناس، وهم يجدونها مكتوبة عندهم في كتبهم، وقال الكلبي: هم اليهود بخلوا أن يصدقوا من أتاهم صفة محمد - صلى الله عليه وسلم - ونعته في كتابهم: وقال مجاهد: الآيات الثلاث إلى قوله: {عليما} نزلت في اليهود.\n(1) - وقال ابن عباس وابن زيد: نزلت في جماعة من اليهود كانوا يأتون رجالا من الأنصار يخالطونهم وينصحونهم ويقولون لهم: لا تنفقوا أموالكم فإنا نخشى عليكم الفقر، فأنزل الله تعالى: {الذين يبخلون ويأمرون الناس بالبخل}"],[43,43,"قوله تعالى: {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى} الآية {43}\nنزلت في أناس من أصحاب رسول الله - صلى الله عليه وسلم - كانوا يشربون الخمر ويحضرون الصلاة وهم نشاوى، فلا يدرون كم يصلون ولا ما يقولون في صلاتهم.\n(2) - أخبرنا أبو بكر الأصفهاني قال: أخبرنا أبو الشيخ الحافظ قال: حدثنا أبو يحيى\nقال: حدثنا سهل بن عثمان قال: حدثنا أبو عبد الرحمن الأفريقي قال: حدثنا عطاء، عن أبي عبد الرحمن قال: صنع عبد الرحمن بن عوف طعاما ودعا أناسا من أصحاب رسول الله - صلى الله عليه وسلم - فطعموا وشربوا، وحضرت صلاة المغرب فتقدم بعض القوم فصلى بهم المغرب، فقرأ: {قل\nيا أيها الكافرون} فلم يقمها، فأنزل الله تعالى: {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون}"],[43,43,"قوله تعالى: {فلم تجدوا ماء فتيمموا صعيدا طيبا} {43} .\nأخبرنا أبو عبد الله ابن أبي إسحاق قال: حدثنا أبو عمرو بن مطر قال: حدثنا إبراهيم بن علي الذهلي قال: حدثنا يحيى بن يحيى قال: قرأت على مالك بن أنس، عن عبد الرحمن بن القاسم عن أبيه، عن عائشة أنها قالت: خرجنا مع رسول الله - صلى الله عليه وسلم - في بعض أسفاره حتى إذا كنا بالبيداء أو بذات الجيش انقطع عقد لي، فأقام رسول الله - صلى الله عليه وسلم - على التماسه، وأقام الناس معه وليسوا على ماء وليس معهم ماء، فأتى الناس إلى أبي بكر، فقالوا: ألا ترى ما صنعت عائشة؟ أقامت برسول الله - صلى الله عليه وسلم - وبالناس معه وليسوا على ماء وليس معهم ماء، فجاء أبو بكر ورسول الله - صلى الله عليه وسلم - واضع رأسه على فخذي قد نام، فقال: أحبست رسول الله والناس معه وليسوا على ماء وليس معهم ماء؟ قالت: فعاتبني أبو بكر وقال: ما شاء الله أن يقول، فجعل يطعن بيده في خاصرتي فلا يمنعني من التحرك إلا مكان رسول الله - صلى الله عليه وسلم - على فخذي، فنام رسول الله - صلى الله عليه وسلم - حتى أصبح على غير ماء، فأنزل الله تعالى آية التيمم\nفتيمموا، فقال أسيد بن\nحضير وهو أحد النقباء: ما هي بأول بركتكم يا آل أبي بكر، قالت عائشة: فبعثنا البعير الذي كنت عليه، فوجدنا العقد تحته. رواه البخاري عن إسماعيل بن أبي أويس، ورواه مسلم عن يحيى بن يحيى، كلاهما عن مالك.\nأخبرنا أبو محمد الفارسي قال: أخبرنا محمد بن عبد الله بن الفضل قال: أخبرنا أحمد بن محمد بن الحسن الحافظ قال: حدثنا محمد بن يحيى قال: حدثنا يعقوب بن إبراهيم بن سعد قال: حدثنا أبي، عن أبي صالح عن ابن شهاب قال: حدثني عبيد الله بن عبد الله بن عتبة، عن ابن عباس، عن عمار بن ياسر قال: عرس رسول الله - صلى الله عليه وسلم - بذات الجيش ومعه عائشة زوجته، فانقطع عقد لها من جذع ظفار، فحبس الناس ابتغاء عقدها ذلك حتى أضاء الفجر وليس معهم ماء فتغيظ عليها أبو بكر وقال: حبست الناس، فأنزل الله تعالى على رسول الله - صلى الله عليه وسلم - قصة التطهر بالصعيد الطيب، فقام المسلمون فضربوا بأيديهم الأرض، ثم رفعوا أيديهم فلم يقبضوا من التراب شيئا، فمسحوا بها وجوههم وأيديهم إلى المناكب وبطون أيديهم إلى الآباط. قال الزهري: وبلغنا أن أبا بكر قال لعائشة: والله إنك ما علمت لمباركة."],[49,49,"قوله تعالى: {ألم تر إلى الذين يزكون أنفسهم} الآية {49} .\nقال الكلبي: نزلت في رجال من اليهود أتوا رسول الله - صلى الله عليه وسلم - بأطفالهم وقالوا: يا محمد. هل على أولادنا هؤلاء من ذنب؟ قال: لا، فقالوا: والذي نحلف به ما نحن إلا كهيئتهم، ما من ذنب نعمله بالنهار إلا كفر عنا بالليل، وما من ذنب نعمله بالليل إلا كفر عنا بالنهار، فهذا الذين زكوا به أنفسهم."],[51,51,"قوله تعالى: {ألم تر إلى الذين أوتوا نصيبا من الكتاب يؤمنون\nبالجبت والطاغوت} {51} .\nأخبرنا محمد بن إبراهيم بن محمد بن يحيى قال: أخبرنا والدي قال: حدثنا محمد بن إسحاق الثقفي قال: حدثنا عبد الجبار بن العلاء قال: حدثنا سفيان، عن عمرو، عن عكرمة قال: جاء حيي بن أخطب وكعب بن الأشرف إلى أهل مكة فقالوا لهم: أنتم أهل الكتاب وأهل العلم القديم، فأخبرونا عنا وعن محمد، فقالوا: ما أنتم وما محمد؟ قالوا: نحن ننحر الكوماء، ونسقي اللبن على الماء، ونفك العاني، ونصل الأرحام، ونسقي الحجيج، وديننا القديم ودين محمد الحديث؛ قالا. بل أنتم خير منه وأهدى سبيلا، فأنزل الله تعالى: {ألم تر إلى الذين أوتوا نصيبا من الكتاب} إلى قوله: {ومن يلعن الله فلن تجد له نصيرا} وقال المفسرون: خرج كعب بن الأشرف في سبعين راكبا من اليهود إلى مكة بعد وقعة أحد ليحالفوا قريشا على رسول الله - صلى الله عليه وسلم - وينقضوا العهد الذي كان بينهم وبين رسول الله - صلى الله عليه وسلم - فنزل كعب على أبي سفيان، ونزلت اليهود في دور قريش، فقال أهل مكة: إنكم أهل كتاب، ومحمد صاحب كتاب، ولا نأمن أن يكون هذا مكرا منكم، فإن أردت أن نخرج معك فاسجد لهذين الصنمين وآمن بهما فذلك قوله: {يؤمنون بالجبت والطاغوت} ثم قال كعب لأهل مكة: ليجيء منكم ثلاثون ومنا ثلاثون فنلزق أكبادنا بالكعبة، فنعاهد رب البيت لنجهدن على قتال محمد، ففعلوا ذلك، فلما فرغوا، قال أبو سفيان لكعب: إنك امرؤ تقرأ الكتاب وتعلم ونحن أميون لا نعلم، فأينا أهدى\nطريقا\nوأقرب إلى الحق؟ أنحن أم محمد؟ فقال كعب: اعرضوا علي دينكم، فقال أبو سفيان: نحن ننحر للحجيج الكوماء، ونسقيهم الماء، ونقري الضيف، ونفك العاني، ونصل الرحم، ونعمر بيت ربنا، ونطوف به، ونحن أهل الحرم، ومحمد فارق دين آبائه، وقطع الرحم، وفارق الحرم، وديننا القديم ودين محمد الحديث؛ فقال كعب: أنتم والله أهدى سبيلا مما هو عليه، فأنزل الله تعالى: {ألم تر إلى الذين أوتوا نصيبا من الكتاب} يعني كعبا وأصحابه الآية."],[52,52,"قوله تعالى: {أولئك الذين لعنهم الله} الآية {52} .\nأخبرنا أحمد بن إبراهيم المقري قال: أخبرنا سفيان بن محمد قال: أخبرنا مكي بن عبدان قال: حدثنا أبو الأزهر قال: حدثنا روح قال: حدثنا سعيد عن قتادة قال: نزلت هذه الآية في كعب بن الأشرف وحيي بن أخطب - رجلين من اليهود من بني النضير - لقيا قريشا بالموسم، فقال لهما المشركون؟ أنحن أهدى أم محمد وأصحابه؟ فإنا أهل السدانة والسقاية، وأهل الحرم، فقالا: بل أنتم أهدى من محمد فهما يعلمان أنهما كاذبان إنما حملهما على ذلك حسد محمد وأصحابه، فأنزل الله تعالى: {أولئك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا} فلما رجعا إلى قومهما قال لهما قومهما: إن محمدا يزعم أنه قد نزل فيكما كذا وكذا، فقالا: صدق والله، ما حملنا على ذلك إلا بغضه وحسده."],[58,58,"قوله تعالى: {إن الله يأمركم أن تؤدوا الأمانات إلى أهلها} {58} .\nنزلت في عثمان بن طلحة الحجبي من بني عبد الدار كان سادن الكعبة، فلما دخل النبي - صلى الله عليه وسلم - مكة يوم الفتح، أغلق عثمان باب البيت وصعد السطح، فطلب رسول الله - صلى الله عليه وسلم -\nالمفتاح، فقيل: إنه مع عثمان، فطلب منه فأبى، وقال: لو علمت أنه رسول الله لم أمنعه المفتاح، فلوى علي بن أبي طالب يده وأخذ منه المفتاح وفتح الباب فدخل رسول الله - صلى الله عليه وسلم - البيت وصلى فيه ركعتين، فلما خرج سأله العباس أن يعطيه المفتاح ليجمع له بين السقاية والسدانة،\nفأنزل الله تعالى هذه الآية، فأمر رسول الله - صلى الله عليه وسلم - عليا أن يرد المفتاح إلى عثمان ويعتذر إليه، ففعل ذلك علي، فقال له عثمان: يا علي أكرهت وآذيت ثم جئت ترفق؟ فقال: لقد أنزل الله تعالى في شأنك، وقرأ عليه هذه الآية، فقال عثمان: أشهد أن محمدا رسول الله وأسلم، فجاء جبريل عليه السلام فقال: \"ما دام هذا البيت فإن المفتاح والسدانة في أولاد عثمان\"، وهو اليوم في أيديهم.\n(1) - أخبرنا أبو حسان المزكي قال: أخبرنا هارون بن محمد الإستراباذي قال: حدثنا أبو محمد الخزاعي قال: حدثنا أبو الوليد الأزرقي قال: حدثنا جدي، عن سفيان، عن سعيد بن سالم، عن ابن جريج عن مجاهد في قول الله تعالى: {إن الله يأمركم أن تؤدوا الأمانات إلى أهلها} قال: نزلت في عثمان بن طلحة، قبض النبي - صلى الله عليه وسلم - مفتاح الكعبة، فدخل الكعبة يوم الفتح، فخرج وهو يتلو هذه الآية، فدعا عثمان فدفع إليه المفتاح وقال: \"خذوها يا بني أبي طلحة بأمانة الله لا ينزعها منكم إلا ظالم\".\nأخبرنا أبو نصر المهرجاني قال: حدثنا عبيد الله بن محمد الزاهد قال: حدثنا أبو القاسم المقري قال: حدثني أحمد بن زهير قال: أخبرنا مصعب قال: حدثنا شيبة بن عثمان بن أبي طلحة قال: دفع النبي - صلى الله عليه وسلم - المفتاح إلي وإلى عثمان وقال: \"خذوها يا بني أبي طلحة خالدة تالدة لا يأخذها منكم إلا ظالم\"، فبنوا أبي طلحة الذين يلون سدانة الكعبة من بني عبد\nالدار."],[59,59,"قوله تعالى: {يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم} {59} .\nأخبرنا أبو عبد الرحمن بن أبي حامد العدل قال: أخبرنا\nأبو بكر بن أبي زكريا الحافظ قال: أخبرنا أبو حامد بن الشرقي قال: حدثنا محمد بن يحيى قال: حدثنا الحجاج بن محمد عن ابن جريج قال: أخبرني يعلى بن مسلم، عن سعيد بن جبير، عن ابن عباس في قوله تعالى: {أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم} قال: نزلت في عبد الله بن حذافة بن قيس بن عدي، بعثه رسول الله - صلى الله عليه وسلم - في سرية. رواه البخاري عن صدقة بن فضل، ورواه مسلم عن زهير بن حرب، كلاهما عن حجاج.\n(1) - وقال ابن عباس في رواية باذان: بعث رسول الله - صلى الله عليه وسلم - خالد بن الوليد في سرية إلى حي من أحياء العرب، وكان معه عمار بن ياسر، فسار خالد حتى إذا دنا من القوم عرس لكي يصبحهم، فأتاهم النذير، فهربوا غير\nرجل قد كان أسلم، فأمر أهله أن يتأهبوا للمسير، ثم انطلق حتى أتى عسكر خالد ودخل على عمار فقال: يا أبا اليقظان إني منكم، وإن قومي لما سمعوا بكم هربوا، وأقمت لإسلامي، أفنافعي ذلك، أو أهرب كما هرب قومي؟ فقال: أقم فإن ذلك نافعك، وانصرف الرجل إلى أهله، وأمرهم بالمقام وأصبح خالد فغار على القوم، فلم يجد غير ذلك الرجل، فأخذه وأخذ ماله، فأتاه عمار فقال: خل سبيل الرجل فإنه مسلم، وقد كنت أمنته وأمرته بالمقام، فقال خالد: أنت تجير علي وأنا الأمير؟ فقال: نعم أنا أجير عليك وأنت الأمير، فكان في ذلك بينهما كلام، فانصرفوا إلى النبي - صلى الله عليه وسلم - فأخبروه خبر الرجل، فأمنه النبي - صلى الله عليه وسلم - وأجاز أمان عمار ونهاه أن يجيز بعد ذلك على أمير بغير إذنه، قال: واستب عمار وخالد بين يدي رسول الله فأغلظ عمار لخالد، فغضب خالد وقال: يا رسول الله أتدع هذا العبد يشتمني، فوالله لولا أنت ما شتمني، وكان عمار مولى لهاشم بن المغيرة، فقال رسول الله - صلى الله عليه وسلم - \"يا خالد كف عن عمار فإنه من يسب عمارا يسبه الله، ومن يبغض عمارا يبغضه الله\"، فقام عمار فتبعه خالد فأخذ بثوبه، وسأله أن يرضى عنه، فرضي عنه، فأنزل الله تعالى هذه الآية، وأمر بطاعة أولي الأمر."],[60,60,"قوله تعالى: {ألم تر إلى الذين يزعمون أنهم آمنوا بما أنزل إليك وما أنزل\nمن قبلك يريدون أن يتحاكموا إلى الطاغوت} الآية {60} .\nأخبرنا\nسعيد بن محمد العدل قال: أخبرنا أبو عمرو بن حمدان قال: أخبرنا الحسن بن سفيان قال: حدثنا إبراهيم بن سعيد الجوهري قال: حدثنا أبو اليمان قال: حدثنا صفوان بن عمرو، عن عكرمة، عن ابن عباس قال: كان أبو بردة الأسلمي كاهنا يقضي بين اليهود فيما يتنافرون إليه، فتنافر إليه أناس من أسلم فأنزل الله تعالى: {ألم تر إلى الذين يزعمون} إلى قوله: {وتوفيقا}\n(1) - أخبرنا أحمد بن محمد بن إبراهيم قال: حدثنا أبو صالح شعيب بن محمد قال: حدثنا أبو حاتم التميمي قال: حدثنا أبو الأزهر قال: حدثنا رويم قال: حدثنا سعيد، عن قتادة قال: ذكر لنا أن هذه الآية أنزلت في رجل من الأنصار يقال له: قيس، وفي رجل من اليهود في مدارأة كانت بينهما في حق تدارءا فيه، فتنافرا إلى كاهن بالمدينة ليحكم بينهما، وتركا نبي الله - صلى الله عليه وسلم - فعاب الله تعالى ذلك عليهما، وكان اليهودي يدعوه إلى نبي الله، وقد علم أنه لن يجور عليه، وجعل الأنصاري يأبى عليه وهو يزعم أنه مسلم ويدعوه إلى الكاهن، فأنزل الله تعالى ما تسمعون، وعاب على الذي يزعم أن مسلم، وعلى اليهودي الذي هو من أهل الكتاب، فقال: {ألم تر إلى الذين يزعمون أنهم آمنوا بما أنزل إليك} إلى قوله: {يصدون عنك صدودا}\n(2) - أخبرني محمد بن عبد العزيز المروزي في كتابه قال: أخبرنا محمد بن الحسين قال: أخبرنا محمد بن يحيى قال: أخبرنا إسحاق الحنظلي قال: أخبرنا المؤمل قال: حدثنا يزيد بن زريع، عن داود، عن الشعبي قال: كان بين رجل من المنافقين ورجل من اليهود خصومة،\nفدعا اليهودي المنافق\nإلى النبي - صلى الله عليه وسلم - لأنه لا يقبل الرشوة، ودعا المنافق اليهودي إلى حاكمهم لأنه علم أنهم يأخذون الرشوة في أحكامهم، فلما اختلفا اجتمعا على أن يحكما كاهنا في جهينة، فأنزل الله تعالى في ذلك: {ألم تر إلى الذين يزعمون أنهم آمنوا بما أنزل إليك} يعني المنافق {وما أنزل من قبلك} يعني اليهودي، {يريدون أن يتحاكموا إلى الطاغوت} إلى قوله: {ويسلموا تسليما}\n(1) - وقال الكلبي عن أبي صالح عن ابن عباس: نزلت في رجل من المنافقين كان بينه وبين يهودي خصومة، فقال اليهودي: انطلق بنا إلى محمد، وقال المنافق: بل نأتي كعب بن الأشرف - وهو الذي سماه الله تعالى الطاغوت - فأبى اليهودي إلا أن يخاصمه إلى رسول الله - صلى الله عليه وسلم - فلما رأى المنافق ذلك أتى معه إلى رسول الله - صلى الله عليه وسلم - فاختصما إليه، فقضى رسول الله - صلى الله عليه وسلم - لليهودي، فلما خرجا من عنده لزمه المنافق وقال: ننطلق إلى عمر بن الخطاب، فأقبلا إلى عمر، فقال اليهودي: اختصمنا أنا وهذا إلى محمد فقضى لي عليه فلم يرض بقضائه، وزعم أنه مخاصم إليك وتعلق بي فجئت إليك معه، فقال عمر للمنافق: أكذلك؟ قال: نعم، فقال لهما: رويدا حتى أخرج إليكما، فدخل عمر البيت وأخذ السيف فاشتمل عليه، ثم خرج إليهما وضرب به المنافق حتى برد، وقال: هكذا أقضي لمن لم يرض بقضاء الله وقضاء رسوله، وهرب اليهودي، ونزلت هذه الآية، وقال جبريل عليه السلام: \"إن عمر فرق بين الحق والباطل\"، فسمي الفاروق.\nوقال السدي: كان ناس من اليهود أسلموا ونافق بعضهم، وكانت قريظة والنضير في الجاهلية إذا قتل رجل من بني قريظة رجلا من بني النضير قتل به وأخذ ديته مائة وسق من\nتمر، وإذا قتل رجل من بني النضير رجلا من قريظة\nلم يقتل به وأعطي ديته ستين وسقا من تمر، وكانت النضير حلفاء الأوس وكانوا أكبر وأشرف من قريظة وهم حلفاء الخزرج، فقتل رجل من النضير رجلا من قريظة واختصموا في ذلك، فقالت بنو النضير: إنا وأنتم كنا اصطلحنا في الجاهلية على أن نقتل منكم ولا تقتلوا منا، وعلى أن ديتكم ستون وسقا - والوسق ستون صاعا - وديتنا مائة وسق فنحن نعطيكم ذلك، فقالت: الخزرج: هذا شيء كنتم فعلتموه في الجاهلية لأنكم كثرتم وقللنا فقهرتمونا، ونحن وأنتم اليوم إخوة وديننا ودينكم واحد، وليس لكم علينا فضل؛ فقال المنافقون: انطلقوا إلى أبي بردة الكاهن الأسلمي؛ وقال المسلمون: لا بل إلى النبي - صلى الله عليه وسلم - فأبى المنافقون وانطلقوا إلى أبي بردة ليحكم بينهم، فقال: أعظموا اللقمة: يعني الرشوة، فقالوا: لك عشرة أوسق، قال: لا، بل مائة وسق ديتي، فإني أخاف إن نفرت النضيري قتلتني قريظة، وإن نفرت القريظي قتلتني النضير، فأبوا أن يعطوه فوق عشر أوسق وأبى أن يحكم بينهم، فأنزل الله تعالى هذه الآية، فدعا النبي - صلى الله عليه وسلم - كاهن أسلم إلى الإسلام، فأبى فانصرف، فقال النبي - صلى الله عليه وسلم - لابنيه: \"أدركا أباكما، فإنه إن جاوز عقبة كذا لم يسلم أبدا\"، فأدركاه فلم يزالا به حتى انصرف وأسلم، وأمر النبي - صلى الله عليه وسلم - مناديا فنادى: \"ألا إن كاهن أسلم قد أسلم\"."],[65,65,"قوله تعالى: {فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم} {65} .\nنزلت في الزبير بن العوام وخصمه حاطب بن أبي بلتعة، وقيل: هو ثعلبة بن حاطب.\n(1) - أخبرنا أبو سعيد عبد الرحمن بن حمدان قال: أخبرنا أحمد بن جعفر بن مالك قال: حدثنا عبد الله بن أحمد بن حنبل قال: حدثني أبي قال: حدثنا أبو اليمان قال: حدثنا شعيب عن الزهري قال: أخبرني عروة بن\nالزبير، عن أبيه، أنه كان يحدث أنه خاصم رجلا من الأنصار قد شهد بدرا إلى النبي - صلى الله عليه وسلم - في شراج الحرة كانا يسقيان بها كلاهما، فقال النبي - صلى الله عليه وسلم - للزبير: \"اسق ثم أرسل إلى جارك\"، فغضب الأنصاري وقال: يا رسول الله، أن كان ابن عمتك؟ فتلون وجه رسول الله - صلى الله عليه وسلم - ثم قال للزبير: \"اسق ثم احبس الماء حتى يرجع إلى الجدر\"، فاستوفى رسول الله - صلى الله عليه وسلم - للزبير حقه، وكان قبل ذلك أشار على الزبير برأي أراد فيه سعة للأنصاري وله، فلما أحفظ الأنصاري رسول الله استوفى للزبير حقه في صريح الحكم، قال عروة: قال الزبير: والله ما أحسب هذه الآية أنزلت إلا في ذلك: {فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما} رواه البخاري عن علي بن عبد الله، عن محمد بن جعفر، عن معمر ورواه مسلم، عن قتيبة، عن الليث، كلاهما عن الزهري.\n(1) - أخبرنا أبو عبد الرحمن بن أبي حامد قال: أخبرنا محمد بن عبد الله بن محمد\nالحافظ قال: حدثنا أبو أحمد محمد بن محمد بن الحسن الشيباني قال: حدثنا أحمد بن حماد بن زغبة قال: حدثنا حامد بن يحيى بن\nهانئ البلخي قال: حدثنا سفيان قال: حدثني عمرو بن دينار عن أبي سلمة عن أم سلمة: أن الزبير بن العوام خاصم رجلا فقضى رسول الله - صلى الله عليه وسلم - للزبير، فقال الرجل: إنما قضى أنه ابن عمته، فأنزل الله تعالى: {فلا وربك لا يؤمنون} الآية."],[69,69,"قوله تعالى: {ومن يطع الله والرسول} الآية {69} .\nقال الكلبي: نزلت في ثوبان مولى رسول الله - صلى الله عليه وسلم - وكان شديد الحب له قليل الصبر عنه، فأتاه ذات يوم وقد تغير لونه ونحل جسمه يعرف في وجهه الحزن، فقال له رسول الله: \"يا ثوبان ما غير لونك؟ \" فقال: يا رسول الله ما بي من ضر ولا وجع غير أني إذا لم أرك اشتقت إليك واستوحشت وحشة شديدة حتى ألقاك، ثم ذكرت الآخرة وأخاف أن لا أراك هناك، لأني أعرف أنك ترفع مع النبيين، وأني وإن دخلت الجنة كنت في منزلة أدنى من منزلتك، وإن لم أدخل الجنة فذاك أحرى أن لا أرك أبدا، فأنزل الله تعالى هذه الآية.\n(1) - أخبرنا إسماعيل بن أبي نصر، أخبرنا إبراهيم النصراباذي قال: أخبرنا عبد الله بن عمر بن علي الجوهري قال: حدثنا عبد الله بن محمود السعدي قال: حدثنا موسى بن يحيى قال: حدثنا عبيدة عن منصور عن مسلم بن صبيح عن مسروق قال: قال أصحاب رسول الله: ما ينبغي لنا أن نفارقك في الدنيا فإنك إذا فارقتنا رفعت فوقنا، فأنزل الله تعالى: {ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين\nوالصديقين}\n(1) - أخبرنا أحمد بن محمد بن إبراهيم قال: حدثنا شعيب قال: حدثنا مكي قال: أخبرنا أبو الأزهر قال: حدثنا روح، عن سعيد، عن قتادة قال: ذكر لنا أن رجلا قال: يا نبي الله أراك في الدنيا فأما في الآخرة فإنك ترفع عنا بفضلك، فلا نراك، فأنزل الله تعالى هذه الآية.\n(2) - أخبرني أبو نعيم الحافظ فيما أذن لي في روايته قال: أخبرنا سليمان بن أحمد اللخمي قال: حدثنا أحمد بن عمرو الخلال قال: حدثنا عبد الله بن عمران العابدي قال: حدثنا فضيل بن عياض، عن منصور، عن إبراهيم، عن الأسود، عن عائشة قالت: جاء رجل إلى رسول الله - صلى الله عليه وسلم - فقال: يا رسول الله إنك لأحب إلي من نفسي وأهلي وولدي، وإني لأكون في البيت فأذكرك فما أصبر حتى آتيك، فأنظر إليك، وإذا ذكرت موتي وموتك عرفت أنك إذا دخلت الجنة رفعت مع النبيين، وإني إذا دخلت الجنة خشيت أن لا أراك، فلم يرد رسول الله - صلى الله عليه وسلم - شيئا حتى نزل جبريل عليه السلام بهذه الآية: {ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين} الآية."],[77,77,"قوله تعالى: {ألم تر إلى الذين قيل لهم كفوا أيديكم} الآية {77} .\nقال الكلبي: نزلت هذه الآية في نفر من أصحاب رسول الله - صلى الله عليه وسلم - منهم عبد الرحمن بن عوف والمقداد بن الأسود وقدامة بن مظعون وسعد بن أبي وقاص كانوا يلقون من\nالمشركين أذى كثيرا ويقولون: يا رسول الله ائذن لنا في قتال هؤلاء، فيقول لهم: \"كفوا أيديكم عنهم فإني لم أؤمر بقتالهم\"، فلما هاجر رسول الله - صلى الله عليه وسلم - إلى المدينة، وأمرهم الله تعالى بقتال المشركين كرهه بعضهم وشق عليهم، فأنزل الله تعالى هذه الآية.\n(1) - أخبرنا سعيد بن محمد بن أحمد العدل قال: أخبرنا أبو عمرو بن حمدان قال: أخبرنا الحسن بن سفيان قال: حدثنا محمد بن علي قال: سمعت أبي يقول: أخبرنا الحسين بن واقد، عن عمرو بن دينار، عن عكرمة، عن ابن عباس: أن عبد الرحمن بن عوف وأصحابه أتوا إلى النبي - صلى الله عليه وسلم - بمكة، فقالوا: يا نبي الله كنا في عز ونحن مشركون، فلما آمنا صرنا أذلة! فقال: \"إني أمرت بالعفو، فلا تقاتلوا والقوم\"، فلما حوله الله إلى المدينة أمره بالقتال فكفوا، فأنزل الله تعالى: {ألم تر إلى الذين قيل لهم كفوا أيديكم}"],[78,78,"قوله تعالى: {أينما تكونوا يدرككم الموت} {78} .\nقال ابن عباس في رواية أبي صالح: لما استشهد الله من المسلمين من استشهد يوم \"أحد\" قال المنافقون الذين تخلفوا عن الجهاد: لو كان إخواننا الذين قتلوا عندنا ما ماتوا وما قتلوا، فأنزل الله تعالى هذه الآية."],[88,88,"قوله تعالى: {فما لكم في المنافقين فئتين} الآية {88} .\nأخبرنا محمد بن إبراهيم بن محمد بن يحيى قال. حدثنا أبو عمرو إسماعيل بن نجيد قال: حدثنا يوسف بن يعقوب القاضي قال: حدثنا عمرو بن مرزوق قال: حدثنا شعبة، عن عدي بن ثابت، عن عبد الله بن يزيد بن ثابت: أن قوما خرجوا مع\nرسول الله - صلى الله عليه وسلم -\nإلى \"أحد\" فرجعوا، فاختلف فيهم المسلمون، فقالت فرقة: نقتلهم، وقالت فرقة: لا نقتلهم، فنزلت هذه الآية. رواه البخاري، عن بندار، عن غندر، ورواه مسلم عن عبد الله بن معاذ عن أبيه، كلاهما عن شعبة.\n(1) - أخبرنا عبد الرحمن بن حمدان العدل قال: أخبرنا أبو بكر أحمد بن جعفر بن مالك قال: حدثنا عبد الله بن أحمد بن حنبل قال: حدثني أبي قال: حدثنا الأسود بن عامر قال: حدثنا حماد بن سلمة، عن محمد بن إسحاق، عن يزيد بن عبد الله بن قسيط، عن أبي سلمة بن عبد الرحمن، عن أبيه: أن قوما من العرب أتوا رسول الله - صلى الله عليه وسلم - فأسلموا وأصابوا وباء المدينة وحماها فأركسوا، فخرجوا من المدينة فاستقبلهم نفر من أصحاب رسول الله - صلى الله عليه وسلم - فقالوا: ما لكم رجعتم؟ فقالوا: أصابنا وباء المدينة فاجتويناها، فقالوا: ما لكم في رسول الله أسوة حسنة؟ فقال بعضهم: نافقوا، وقال بعضهم: لم ينافقوا هم مسلمون، فأنزل الله تعالى: {فما لكم في المنافقين فئتين والله أركسهم بما كسبوا} الآية.\nوقال مجاهد في هذه الآية: هم قوم خرجوا من مكة حتى جاءوا المدينة يزعمون أنهم مهاجرون، ثم ارتدوا بعد ذلك، فاستأذنوا النبي عليه الصلاة والسلام أن يخرجوا إلى مكة ليأتوا ببضائع لهم يتجرون فيها، فاختلف فيهم المؤمنون، فقائل يقول: هم منافقون، وقائل يقول: هم مؤمنون، فبين الله\nتعالى نفاقهم وأنزل هذه الآية، وأمر بقتلهم في قوله: {فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم} (1) فجاءوا ببضائعهم يريدون هلال\nبن عويمر الأسلمي وبينه وبين النبي - صلى الله عليه وسلم - حلف، وهو الذي حصر صدره أن يقاتل المؤمنين، فرفع عنهم القتل بقوله تعالى: {إلا الذين يصلون إلى قوم} (2) الآية."],[92,92,"قوله تعالى: {وما كان لمؤمن أن يقتل مؤمنا إلا خطأ} {92} .\nأخبرنا أبو عبد الله بن أبي إسحاق قال: أخبرنا أبو عمرو بن نجيد قال: حدثنا أبو مسلم إبراهيم بن عبد الله قال: حدثنا ابن حجاج قال: حدثنا حماد قال: أخبرنا محمد بن إسحاق، عن عبد الرحمن بن القاسم، عن أبيه: أن الحارث بن يزيد كان شديدا على النبي - صلى الله عليه وسلم - فجاء وهو يريد الإسلام، فلقيه عياش بن أبي ربيعة والحارث يريد الإسلام وعياش لا يشعر فقتله، فأنزل الله تعالى: {وما كان لمؤمن أن يقتل مؤمنا إلا خطأ} الآية.\nوشرح الكلبي هذه القصة فقال: إن عياش بن أبي ربيعة المخزومي أسلم وخاف أن يظهر إسلامه، فخرج هاربا إلى المدينة فقدمها، ثم أتى أطما من آطامها، فتحصن فيه فجزعت أمه جزعا شديدا وقالت لابنيها أبي جهل والحارث بن هاشم وهما لأمه: لا يظلني سقف بيت ولا أذوق طعاما ولا شرابا حتى تأتوني به، فخرجا في طلبه، وخرج معهم الحارث بن زيد بن أبي أنيسة حتى أتوا المدينة، فأتوا عياشا وهو في الأطم، فقالا: انزل فإن أمك لم يؤوها سقف بيت بعدك، وقد حلفت لا تأكل طعاما ولا شرابا حتى ترجع إليها،\nولك الله علينا أن لا نكرهك على شيء ولا تحول بينك وبين دينك، فلما ذكرا له\nجزع أمه وأوثقا له نزل إليهم فأخرجوه من المدينة وأوثقوه بنسع وجلده كل واحد منهم مائة جلدة، ثم قدموا به على أمه فقالت: والله لا أحلك من وثاقك حتى تكفر بالذي آمنت به ثم تركوه موثقا في الشمس، وأعطاهم بعض الذي أرادوا، فأتاه الحارث بن يزيد وقال: يا عياش، والله لئن كان الذي كنت عليه هدى لقد تركت الهدى، وإن كان ضلالة لقد كنت عليها، فغضب عياش من مقاله وقال: والله لا ألقاك خاليا إلا قتلتك، ثم إن عياشا أسلم بعد ذلك وهاجر إلى رسول الله - صلى الله عليه وسلم - بالمدينة، ثم إن الحارث بن يزيد أسلم وهاجر بعد ذلك إلى رسول الله بالمدينة وليس عياش يومئذ حاضرا ولم يشعر بإسلامه، فبينا هو يسير بظهر قباء إذ لقي الحارث بن يزيد، فلما رآه حمل عليه فقتله، فقال الناس: أي شيء صنعت؟ إنه قد أسلم، فرجع عياش إلى رسول الله - صلى الله عليه وسلم - فقال: يا رسول الله كان من أمري وأمر الحارث ما قد علمت: وإني لم أشعر بإسلامه حين قتلته، فنزل عليه السلام بقوله: {وما كان لمؤمن أن يقتل مؤمنا إلا خطأ}"],[93,93,"قوله تعالى: {ومن يقتل مؤمنا متعمدا} الآية {93}\nوقال الكلبي عن أبي صالح، عن ابن عباس: إن مقيس بن صبابة وجد أخاه هشام بن ضبابة قتيلا في بني النجار وكان مسلما، فأتى رسول الله - صلى الله عليه وسلم - فذكر له ذلك، فأرسل رسول الله - صلى الله عليه وسلم - معه رسولا من بني فهر؛ فقال: \"ائت بني النجار فأقرئهم السلام وقل لهم: إن رسول الله - صلى الله عليه وسلم - يأمركم إن علمتم قاتل هشام بن ضبابة أن تدفعوه إلى أخيه فيقتص منه، وإن لم تعلموا له قاتلا أن تدفعوا إليه ديته\"، فأبلغهم الفهري ذلك عن النبي - صلى الله عليه وسلم - فقالوا: سمعا وطاعة لله ولرسوله، والله ما نعلم له قاتلا، ولكن نؤدي إليه ديته، فأعطوه\nمائة من الإبل ثم انصرفا\nراجعين نحو المدينة، وبينهما وبين المدينة قريب، فأتى الشيطان مقيسا فوسوس إليه فقال: أي شيء صنعت؟ تقبل دية أخرجه فيكون عليك سبة؟ اقتل الذي معك فيكون نفس مكان نفس وفضل الدية، ففعل مقيس ذلك، فرمى الفهري بصخرة فشدخ رأسه، ثم ركب بعيرا منها وساق بقيتها راجعا إلى مكة كافرا، وجعل يقول في شعره:\nقتلت به فهرا وحملت عقله سراة بني النجار أرباب فارع\nوأدركت ثأري واضطجعت موسدا وكنت إلى الأوثان أول راجع\nفنزلت هذه الآية: {ومن يقتل مؤمنا متعمدا} الآية. ثم أهدر النبي - صلى الله عليه وسلم - دمه يوم فتح مكة، فأدركه الناس بالسوق فقتلوه."],[94,94,"قوله تعالى: {يا أيها الذين آمنوا إذا ضربتم في سبيل الله فتبينوا} {94}\nأخبرنا أبو إبراهيم إسماعيل بن إبراهيم الواعظ قال: أخبرنا أبو الحسين محمد بن أحمد بن حامد قال: أخبرنا أحمد بن الحسين بن عبد الجبار قال: حدثنا محمد بن عباد قال: حدثنا سفيان عن عمرو، عن عطاء، عن ابن عباس قال: لحق المسلمون رجلا في غنيمة له، فقال: السلام عليكم، فقتلوه وأخذوا غنيمته، فنزلت هذه الآية: {ولا تقولوا لمن ألقى إليكم السلام لست مؤمنا تبتغون عرض الحياة الدنيا} أي تلك الغنيمة، رواه البخاري عن علي بن عبد الله. ورواه مسلم عن أبي بكر بن أبي شيبة، كلاهما عن سفيان.\n(1) - وأخبرنا إسماعيل قال: أخبرنا أبو عمرو بن نجيد قال: حدثنا محمد بن الحسن بن الخليل قال: حدثنا أبو كريب قال: حدثنا عبيد الله، عن إسرائيل، عن سماك، عن عكرمة، عن ابن عباس قال: مر رجل من سليم على نفر من أصحاب رسول الله - صلى الله عليه وسلم - ومعه غنم له فسلم عليهم، فقالوا: ما سلم عليكم إلا ليتعوذ منكم، فقاموا إليه فقتلوه، وأخذوا غنمه وأتوا بها رسول الله - صلى الله عليه وسلم - فأنزل الله تعالى: {يا أيها الذين آمنوا إذا ضربتم في سبيل الله فتبينوا}\n(2) - أخبرنا أبو بكر الأصفهاني قال: أخبرنا أبو الشيخ الحافظ قال: أخبرنا أبو يحيى الرازي قال: حدثنا سهل بن عثمان قال: حدثنا وكيع عن سفيان، عن حبيب بن أبي عمرة عن سعيد بن جبير قال: خرج المقداد بن\nالأسود في سرية، فمروا برجل في غنيمة له، فأرادوا قتله، فقال: لا إله إلا الله، فقتله المقداد، فقيل له: أقتلته وقد قال لا إله إلا الله ود لو فر بأهله وماله؟ فلما قدموا على رسول الله - صلى الله عليه وسلم - ذكروا ذلك له، فنزلت: {يا أيها الذين آمنوا إذا ضربتم في سبيل الله فتبينوا}\nوقال الحسن: إن أصحاب النبي - صلى الله عليه وسلم - خرجوا يطوفون، فلقوا المشركين فهزموهم، فشد\nمنهم رجل فتبعه رجل من المسلمين وأراد متاعه، فلما غشيه بالسنان قال: إني مسلم، إني مسلم، فكذبه ثم أوجره السنان فقتله، وأخذ متاعه وكان قليلا، فرفع ذلك إلى رسول الله فقال: \"قتلته بعدما زعم أنه مسلم؟ \". فقال: يا رسول الله إنما قالها متعوذا، قال: \"فهلا شققت عن قلبه\"، قال: لم يا رسول الله؟ قال: \"لتنظر أصادق هو أم كاذب؟ \" قال: وكنت أعلم ذلك يا رسول الله؟ قال: \"ويلك إنك إن لم تكن تعلم ذلك، إنما كان يبين عنه لسانه\"، قال: فما لبث القاتل أن مات، فدفن فأصبح وقد وضع إلى جنب قبره قال: ثم عادوا فحفروا له، وأمكنوا ودفنوه، فأصبح وقد وضع إلى جنب قبره مرتين أو ثلاثا، فلما رأوا أن الأرض لا تقبله ألقوه في بعض تلك الشعاب، قال: وأنزل الله تعالى هذه الآية. قال الحسن: إن الأرض تجن من هو شر منه، ولكن وعظ القوم أن لا يعودوا.\n(1) - أخبرنا أبو نصر أحمد بن محمد المزكي قال: أخبرنا عبيد الله بن\nمحمد بن بطة قال: أخبرنا أبو القاسم البغوي قال: حدثنا سعيد بن يحيى الأموي قال: حدثني أبي قال: حدثنا محمد بن إسحاق عن يزيد بن عبد الله بن قسيط، عن القعقاع بن عبد الله بن أبي حدرد عن أبيه قال: بعثنا رسول الله - صلى الله عليه وسلم - في سرية إلى إضم قبل مخرجه إلى مكة قال: فمر بنا عامر بن الأضبط الأشجعي فحيانا تحية الإسلام، فنزعنا عنه وحمل عليه محلم بن جثامة لشر كان، بينه وبينه في الجاهلية، فقتله واستلب بعيرا له ووطاء ومتيعا كان له. قال: فأنهينا شأننا إلى رسول الله - صلى الله عليه وسلم - فأخبرناه بخبره، فأنزل الله تعالى: {يا أيها الذين آمنوا إذا ضربتم في سبيل الله فتبينوا} إلى آخر الآية.\nوقال السدي: بعث رسول الله - صلى الله عليه وسلم - أسامة بن زيد على سرية، فلقي مرداس بن نهيك الضمري فقتله، وكان من أهل فدك ولم يسلم من قومه غيره، وكان يقول: لا إله إلا الله محمد رسول الله، ويسلم عليهم، قال أسامة: فلما قدمت على رسول الله - صلى الله عليه وسلم - أخبرته فقال: \"قتلت رجلا يقول: لا إله إلا الله؟ \" فقلت: يا رسول الله إنما تعوذ من القتل، فقال: \"كيف أنت إذا خاصمك يوم القيامة بلا إله إلا الله؟ \" قال: فما زال يرددها علي: \"أقتلت رجلا يقول لا إله إلا الله؟ \" حتى تمنيت لو أن إسلامي كان يومئذ، فنزلت: {إذا ضربتم في سبيل الله فتبينوا} الآية.\n(1) - ونحو هذا قال الكلبي وقتادة.\nويدل على صحته الحديث الذي أخبرناه أبو بكر محمد بن إبراهيم الفارسي قال: أخبرنا محمد بن عيسى بن عمرويه قال: حدثنا إبراهيم بن سفيان قال: حدثنا مسلم قال: حدثني يعقوب الدورقي قال: حدثنا هشيم\nقال: أخبرنا ابن حصين قال: حدثنا أبو ظبيان قال: سمعت أسامة بن زيد بن حارثة يحدث قال: بعثنا النبي - صلى الله عليه وسلم - إلى الحرقة من جهينة، فصبحنا القوم فهزمناهم قال: ولحقت أنا ورجل من الأنصار رجلا منهم، فلما غشيناه قال: لا إله إلا الله، قال: فكف عنه الأنصار فطعنته برمحي ففتلته، فلما قدمنا بلغ ذلك النبي - صلى الله عليه وسلم - فقال: \"يا أسامة أقتلته بعدما قال لا إله إلا الله؟ \" قلت: يا رسول الله إنما كان متعوذا، قال: أقتلته بعدما قال لا إله إلا الله؟ \" قال: ما زال يكررها علي حتى تمنيت أني لم أكن أسلمت قبل ذلك اليوم."],[95,95,"قوله تعالى: {لا يستوي القاعدون من المؤمنين} الآية {95} .\nأخبرنا أبو عثمان سعيد بن محمد العدل قال: أخبرنا جدي قال: أخبرنا محمد بن إسحاق السراج قال: حدثنا محمد بن حميد الرازي قال: حدثنا سلمة بن الفضل، عن محمد بن إسحاق، عن الزهري، عن سهل بن سعد، عن مروان بن الحكم، عن زيد بن ثابت قال: كنت عند النبي - صلى الله عليه وسلم - حين نزلت عليه: {لا يستوي القاعدون من المؤمنين غير أولي الضرر والمجاهدون في سبيل الله} ولم يذكر أولي الضرر، فقال ابن أم مكتوم: كيف وأنا أعمى لا أبصر، قال زيد: فتغشى النبي - صلى الله عليه وسلم - في مجلسه الوحي، فاتكأ على فخذي، فوالذي نفسي بيده لقد ثقل على فخذي حتى خشيت أن يرضها، ثم سري عنه فقال: \"اكتب:\n{لا يستوي القاعدون من المؤمنين غير أولي الضرر} فكتبتها. رواه البخاري، عن إسماعيل بن عبد الله، عن إبراهيم بن سعد، عن صالح، عن الزهري.\n(1) - أخبرنا محمد بن إبراهيم بن محمد بن يحيى قال: أخبرنا محمد بن جعفر بن مطر قال: أخبرنا أبو خليفة قال: حدثنا أبو الوليد قال: حدثنا شعبة قال: أنبأنا أبو إسحاق سمعت البراء يقول: لما نزلت هذه الآية: {لا يستوي القاعدون} دعا رسول الله - صلى الله عليه وسلم - زيدا، فجاء بكتف وكتبها، فشكا ابن أم مكتوم ضرارته، فنزلت: {لا يستوي القاعدون من المؤمنين غير أولي الضرر} رواه البخاري عن أبي الوليد، ورواه مسلم عن\nبندار، عن غندر، كلاهما عن شعبة.\n(2) - أخبرنا إسماعيل بن أبي القاسم النصراباذي قال: أخبرنا إسماعيل بن نجيد قال: أخبرنا محمد بن عبدوس قال: حدثنا علي بن الجعد\nقال: حدثنا زهير، عن أبي إسحاق، عن البراء، عن رسول الله - صلى الله عليه وسلم - أنه قال: \"ادع لي زيدا وقل له يجيء بالكتف والدواة أو اللوح\"، وقال: \"اكتب لي {لا يستوي القاعدون من المؤمنين} أحسبه قال: {والمجاهدون في سبيل الله} \" فقال ابن أم مكتوم: يا رسول الله بعيني ضرر، قال: فنزلت قبل أن يبرح: {غير أولي الضرر} رواه البخاري عن محمد بن يوسف، عن إسرائيل، عن أبي إسحاق."],[97,97,"قوله تعالى: {إن الذين توفاهم الملائكة ظالمي أنفسهم} الآية {97} .\nنزلت هذه الآية في ناس من أهل مكة تكلموا بالإسلام ولم يهاجروا وأظهروا الإيمان وأسروا النفاق، فلما كان يوم بدر خرجوا مع المشركين إلى حرب المسلمين فقتلوا، فضربت الملائكة وجوههم وأدبارهم، وقالوا لهم ما ذكر الله سبحانه.\n(1) - أخبرنا أبو بكر الحارثي قال: أخبرنا أبو الشيخ الحافظ قال: أخبرنا أبو يحيى قال: حدثنا سهل بن عثمان قال: حدثنا عبد الرحيم بن سليمان، عن أشعث بن سوار عن عكرمة، عن ابن عباس: {إن الذين توفاهم الملائكة\nظالمي أنفسهم} وتلاها إلى آخرها قال: كانوا قوما من المسلمين بمكة، فخرجوا في قوم من المشركين في قتال فقتلوا معهم، فنزلت هذه الآية."],[100,100,"قوله تعالى: {ومن يخرج من بيته مهاجرا إلى الله ورسوله} {100} .\nقال ابن عباس في رواية عطاء: كان عبد الرحمن بن عوف يخبر أهل مكة بما ينزل فيهم من القرآن، فكتب الآية التي نزلت: {إن الذين توفاهم الملائكة ظالمي أنفسهم} فلما قرأها المسلمون قال حبيب بن ضمرة الليثي لبنيه وكان شيخا كبيرا: احملوني فإني لست من المستضعفين وإني لا أهتدي إلى الطريق. فحمله بنوه على سرير متوجها إلى المدينة، فلما بغل \"التنعيم\" أشرف على الموت، فصفق يمينه على شماله وقال: اللهم هذه لك وهذه لرسولك أبايعك على ما بايعتك يد رسول الله - صلى الله عليه وسلم - ومات حميدا، فبلغ خبره أصحاب رسول الله - صلى الله عليه وسلم - فقالوا: لو وافى المدينة لكان أتم أجرا، فأنزل الله تعالى فيه هذه الآية.\n(1) - أخبرنا أبو حسان المزني قال: أخبرنا هارون بن محمد بن هارون قال: أخبرنا إسحاق بن محمد الخزاعي قال: حدثنا أبو الوليد الأزرقي قال: حدثنا جدي قال: حدثنا سفيان بن عيينة، عن عمرو بن دينار، عن عكرمة\nقال: كان بمكة ناس قد دخلهم الإسلام ولم يستطيعوا الهجرة، فلما كان يوم بدر وخرج بهم كرها فقتلوا، أنزل الله تعالى: {إن الذين توفاهم الملائكة ظالمي أنفسهم} إلى قوله تعالى: {عسى الله أن يعفو عنهم} إلى آخر الآية. قال: وكتب بذلك من كان بالمدينة إلى من بمكة ممن أسلم، فقال رجل من بني بكر كان مريضا: إلى \"الروحاء\" فخرجوا به، فخرج يريد المدينة، فلما بلغ \"الحصحاص\" مات، فأنزل الله تعالى: {ومن يخرج من بيته مهاجرا إلى الله ورسوله}"],[102,102,"قوله تعالى: {وإذا كنت فيهم فأقمت لهم الصلاة} {102} .\nأخبرنا الأستاذ أبو عثمان الزعفراني المقري سنة خمس وعشرين قال: أخبرنا أبو محمد\nعبد الله بن محمد بن علي بن زياد السدي سنة ثلاث وستين قال: أخبرنا أبو سعيد الفضل بن محمد الجزري بمكة في المسجد الحرام سنة أربع وثلثمائة قال: أخبرنا علي بن زياد اللحجي قال: حدثنا أبو قرة: موسى بن طارق قال: ذكر سفيان عن منصور، عن مجاهد قال: حدثنا أبو عياش الزرقي قال: صلينا مع رسول الله صلى الله عليه وآله وسلم الظهر، فقال المشركون: قد كانوا على حال لو كنا أصبنا منهم غرة، قالوا: تأتي عليهم صلاة هي أحب إليهم من آبائهم قال: وهي العصر، قال: فنزل جبريل عليه السلام بهؤلاء الآيات بين الأولى والعصر: {وإذا كنت فيهم فأقمت لهم الصلاة} وهم بعسفان، وعلى المشركين خالد بن الوليد وهم بيننا وبين القبلة، وذكر صلاة الخوف. أخبرنا عبد الرحمن بن عبدان قال: حدثنا محمد بن عبد الله بن محمد الضبي قال: حدثنا محمد بن يعقوب قال: حدثنا أحمد بن عبد الجبار قال: حدثنا يونس بن بكير عن النضر أبي عمر، عن عكرمة، عن ابن عباس قال: خرج رسول الله - صلى الله عليه وسلم - فلقي المشركين بعسفان، فلما صلى رسول الله عليه الصلاة والسلام الظهر فرأوه يركع ويسجد هو وأصحابه، قال بعضهم لبعض: كان هذا فرصة لكم لو أغرتم عليهم ما علموا بكم حتى تواقعوهم، فقال قائل منهم: فإن لهم صلاة أخرى هي أحب إليهم من أهليهم وأموالهم، فاستعدوا حتى تغيروا عليهم فيها، فأنزل الله تعالى تبارك وتعالى على نبيه: {وإذا كنت فيهم فأقمت لهم الصلاة} إلى آخر الآية، وأعلم ما ائتمر به المشركون، وذكر صلاة الخوف."],[105,105,"قوله تعالى: {إنا أنزلنا إليك الكتاب بالحق لتحكم بين الناس بما أراك الله} الآية {105} . إلى قوله تعالى: {ومن يشرك بالله فقد ضل ضلالا بعيدا}\nأنزلت كلها في قصة واحدة. وذلك أن رجلا من الأنصار يقال له: طعمة بن أبيرق أحد بني ظفر بن الحارث سرق درعا من جار له يقال له: قتادة بن النعمان، وكانت الدرع في جراب فيه دقيق، فجعل الدقيق ينتثر من خرق في الجراب حتى انتهى إلى الدار وفيها أثر الدقيق، ثم خبأها عند رجل من اليهود يقال له: زيد بن السمين، فالتمست الدرع عند طعمة فلم توجد عنده وحلف لهم: والله ما أخذها وما له به من علم، فقال أصحاب الدرع: بلى والله قد أدلج علينا فأخذها وطلبنا أثره حتى دخل داره، فرأينا أثر الدقيق. فلما أن حلف تركوه واتبعوا أثر الدقيق حتى انتهوا إلى منزل اليهودي فأخذوه، فقال: دفعها إلي طعمة بن أبيرق، وشهد له أناس من اليهود على ذلك، فقالت بنو ظفر وهم قوم طعمة: انطلقوا بنا إلى رسول الله صلى الله عليه وآله وسلم، فكلموه في ذلك، فسألوه أن يجادل عن صاحبهم، وقالوا: إن لم تفعل هلك صاحبنا وافتضح وبرئ اليهودي، فهم رسول الله صلى الله عليه وآله وسلم أن يفعل، وكان هواه معهم وأن يعاقب اليهودي، حتى أنزل الله تعالى: {إنا أنزلنا إليك الكتاب بالحق} الآية كلها، وهذا قول جماعة من المفسرين."],[123,123,"قوله تعالى: {ليس بأمانيكم ولا أماني أهل الكتاب} {123} .\nأخبرنا أبو بكر التميمي قال: أخبرنا أبو محمد بن حيان قال: حدثنا أبو يحيى قال: حدثنا سهل قال: حدثنا علي بن مسهر عن إسماعيل بن أبي خالد، عن أبي صالح قال: جلس أهل الكتاب - أهل التوارة وأهل الإنجيل - وأهل الأديان كل صنف يقول لصاحبه: نحن خير منكم، فنزلت هذه الآية.\nوقال مسروق وقتادة: احتج المسلمون وأهل الكتاب، فقال أهل الكتاب: نحن أهدى منكم، نبينا قبل نبيكم، وكتابنا قبل كتابكم، ونحن أولى بالله منكم؛ وقال المسلمون: نحن أهدى منكم وأولى بالله، نبينا خاتم الأنبياء، وكتابنا يقضي على الكتب التي قبله، فأنزل الله تعالى هذه الآية، ثم أفلج الله حجة المسلمين على من ناوأهم من أهل الأديان بقوله تعالى: {ومن يعمل من الصالحات من ذكر أو أنثى وهو مؤمن} وبقوله تعالى: {ومن أحسن دينا ممن أسلم وجهه لله} الآيتين."],[125,125,"قوله تعالى: {واتبع ملة إبراهيم حنيفا واتخذ الله إبراهيم خليلا} {125} .\nاختلفوا في سبب اتخاذ الله إبراهيم خليلا: فأخبرنا أبو سعيد النضروي قال: أخبرنا أبو الحسن محمد بن الحسن السراج قال: أخبرنا محمد بن عبد الله الحضرمي قال: حدثنا موسى بن إبراهيم المروزي قال: حدثنا ابن لهيعة، عن أبي قبيل، عن عبد الله، عن عمر قال: قال رسول الله صلى الله عليه وآله\nوسلم: \"يا جبريل لم اتخذ الله إبراهيم خليلا\"؟ قال: لإطعامه الطعام يا محمد\".\nوقال عبد الله بن عبد الرحمن بن أبزى: دخل إبراهيم فجاءه ملك الموت في صورة شاب لا يعرفه، قال له إبراهيم: بإذن من دخلت؟ فقال: بإذن رب المنزل، فعرفه إبراهيم عليه السلام، فقال له ملك الموت: إن ربك اتخذ من عباده خليلا، قال إبراهيم: ومن ذلك؟ قال: وما تصنع به؟ قال: أكون خادما له حتى أموت، قال: فإنه أنت.\nوقال الكلبي عن أبي صالح عن ابن عباس: أصاب الناس سنة جهدوا فيها، فحشروا إلى باب إبراهيم عليه الصلاة والسلام يطلبون الطعام وكانت الميرة له كل سنة من صديق له بمصر، فبعث غلمانه بالإبل إلى خليله بمصر يسأله الميرة، فقال خليله: لو كان إبراهيم إنما يريده لنفسه احتملنا ذلك له، وقد دخل علينا ما دخل على الناس من الشدة، فرجع رسل إبراهيم، فمروا ببطحاء، فقالوا: لو احتملنا من هذه البطحاء ليرى الناس أنا قد جئنا بالميرة، إنا نستحيي أن نمر بهم وإبلنا فارغة، فملأوا تلك الغرائر رملا، ثم إنهم أتوا إبراهيم عليه الصلاة وسارة نائمة فأعلموه ذلك، فاهتم إبراهيم عليه السلام بمكان الناس، فغلبته عيناه فنام، واستيقظت سارة، فقامت إلى تلك الغرائر ففتقتها، فإذا هو دقيق أجود حوارى يكون، فأمرت الخبازين فخبزوا وأطعموا الناس واستيقظ إبراهيم عليه السلام فوجد ريح الطعام، فقال: يا سارة من أين هذا الطعام؟ قالت: من عند خليلك المصري، فقال: بل من عند خليلي الله لا من عند خليلي المصري، فيومئذ اتخذ الله إبراهيم خليلا.\nأخبرنا أبو عبد الله محمد بن إبراهيم المزكي قال: أخبرنا أبو عبد الله محمد بن يزيد الجوزي قال: حدثنا إبراهيم ابن شريك قال: حدثنا أحمد بن يونس قال: حدثنا أبو بكر بن عياش، عن أبي المهلب الكناني، عن\nعبيد الله بن زحر، عن علي بن يزيد، عن القاسم بن أبي أمامة قال: قال رسول الله - صلى الله عليه وسلم - \"إن الله اتخذني خليلا كما اتخذ إبراهيم خليلا، وإنه لم يكن نبي إلا له خليل، ألا وإن خليلي أبو بكر\".\nوأخبرني الشريف أبو إسماعيل بن الحسن النقيب قال: أخبرنا جدي قال: أخبرنا أبو محمد الحسن بن حماد قال: أخبرنا أبو إسماعيل محمد بن إسماعيل الترمذي قال: أخبرنا سعيد بن أبي مريم قال: حدثنا سلمة قال: حدثني زيد ابن واقد، عن القاسم بن مخيمرة، عن أبي هريرة قال: قال رسول الله - صلى الله عليه وسلم - \"اتخذ الله إبراهيم خليلا، وموسى نجيا، واتخذني حبيبا، ثم قال: وعزتي لأوثرن حبيبي على خليلي ونجيي\"."],[127,127,"قوله تعالى: {ويستفتونك في النساء} الآية {127} .\nأخبرنا أبو بكر أحمد بن الحسن القاضي قال: حدثنا محمد بن يعقوب قال: أخبرنا محمد بن عبد الله بن عبد الحكم قال: حدثنا ابن وهب قال: أخبرني يونس، عن ابن شهاب قال: أخبرني عروة بن الزبير، عن عائشة قالت: ثم إن الناس استفتوا رسول الله - صلى الله عليه وسلم - بعد هذه الآية فيهن، فأنزل الله تعالى هذه الآية: {ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلى عليكم في الكتاب} الآية. قالت: والذي يتلى عليهم في الكتاب الآية الأولى التي قال فيها: {وإن خفتم ألا تقسطوا في اليتامى} قالت عائشة رضي الله عنها: وقال الله تعالى في الآية الأخرى: {وترغبون أن تنكحوهن} رغبة أحدكم عن يتيمته التي تكون في حجره حين تكون قليلة المال والجمال، فنهوا أن ينكحوا ما رغبوا في مالها\nوجمالها من يتامى النساء إلا بالقسط من أجل رغبتهم عنهن. رواه مسلم عن حرملة عن ابن وهب."],[128,128,"قوله تعالى: {وإن امرأة خافت} الآية {128} .\nأخبرنا أحمد بن محمد بن أحمد بن الحارث قال: أخبرنا عبد الله بن محمد بن جعفر قال: حدثنا أبو يحيى قال: حدثنا سهل قال: حدثنا عبد الرحمن بن سليمان، عن هشام، عن عروة، عن عائشة في قول الله تعالى: {وإن امرأة خافت من بعلها نشوزا} إلى آخر الآية: نزلت في المرأة تكون عند الرجل فلا يستكثر منها ويريد فراقها، ولعلها أن تكون لها صحبة ويكون لها ولد فيكره فراقها، وتقول له: لا تطلقني وأمسكني وأنت في حل من شأني، فأنزلت هذه الآية. رواه البخاري عن محمد بن مقاتل عن ابن المبارك، ورواه مسلم عن أبي كريب وأبي أسامة، كلاهما عن هشام.\n(2) - أخبرنا أبو بكر الحيري قال: حدثنا محمد بن يعقوب قال: أخبرنا الربيع قال: أخبرنا الشافعي قال: أخبرنا ابن عيينة، عن الزهري، عن ابن\nالمسيب: أن بنت محمد بن مسلمة كان عند رافع بن خديج فكره منها أمرا، إما كبرا وإما غيره، فأراد طلاقها، فقالت: لا تطلقني وأمسكني واقسم لي ما بدا لك، فأنزل الله تعالى: {وإن امرأة خافت\nمن بعلها نشوزا أو إعراضا}"],[135,135,"قوله تعالى: {يا أيها الذين آمنوا كونوا قوامين بالقسط} الآية {135} .\nروى أسباط عن السدي قال: نزلت في النبي - صلى الله عليه وسلم - اختصم إليه غني وفقير، وكان ضلعه مع الفقير، رأى أن الفقير لا يظلم الغني فأبى الله تعالى إلا أن يقوم بالقسط في الغني والفقير، فقال: {يا أيها الذين آمنوا كونوا قوامين بالقسط} حتى بلغ {إن يكن غنيا أو فقيرا فالله أولى بهما}"],[136,136,"قوله تعالى: {يا أيها الذين آمنوا آمنوا بالله ورسوله} الآية {136} .\nقال الكلبي: نزلت في عبد الله بن سلام وأسد وأسيد ابني كعب وثعلبة بن قيس وجماعة من مؤمني أهل الكتاب، قالوا: يا رسول الله إنا نؤمن بك وبكتابك وبموسى والتوراة وعزير، ونكفر بما سواه من الكتب والرسل، فأنزل الله تعالى هذه الآية."],[148,148,"قوله: {لا يحب الله الجهر بالسوء من القول} الآية {148} .\nقال مجاهد. إن ضيفا تضيف قوما فأساءوا قراه فاشتكاهم، فنزلت هذه الآية رخصة في أن يشكوا."],[153,153,"قوله تعالى: {يسألك أهل الكتاب أن تنزل عليهم كتابا} الآية {153} .\nنزلت في اليهود قالوا للنبي - صلى الله عليه وسلم - إن كنت نبيا فأتنا بالكتاب جملة من السماء كما أتى به موسى، فأنزل الله تعالى هذه الآية."],[166,166,"قوله تعالى: {لكن الله يشهد بما أنزل إليك} الآية {166} .\nقال الكلبي: إن رؤساء أهل مكة أتوا رسول الله - صلى الله عليه وسلم - فقالوا: سألنا عنك اليهود فزعموا\nأنهم لا يعرفونك، فأتنا بمن يشهد لك أن الله بعثك إلينا رسولا، فنزلت هذه الآية: {لكن الله يشهد}"],[171,171,"قوله تعالى: {لا تغلوا في دينكم} الآية {171} .\nنزلت في طوائف من النصارى حين قالوا عيسى ابن الله، فأنزل الله تعالى: {لا تغلوا في دينكم ولا تقولوا على الله إلا الحق} الآية."],[172,172,"قوله تعالى: {لن يستنكف المسيح} الآية {172} .\nقال الكلبي: إن وفد نجران قالوا: يا محمد تعيب صاحبنا؟ قال: \"ومن صاحبكم؟ \" قالوا: عيسى، قال: \"وأي شيء أقول فيه؟ \" قالوا تقول إنه عبد الله ورسوله، فقال لهم: \"إنه ليس بعار لعيسى أن يكون عبد الله\"، قالوا: بلى، فنزلت: {لن يستنكف المسيح أن يكون عبدا لله} الآية."],[176,176,"قوله: {يستفتونك قل الله يفتيكم في الكلالة} الآية {176} .\nأخبرنا أبو عبد الرحمن بن أبي حامد قال: حدثنا زاهر بن أحمد قال: حدثنا الحسين بن\nمحمد بن مصعب قال: حدثنا يحيى بن حكيم قال: حدثنا ابن أبي عدي، عن هشام بن أبي عبد الله، عن أبي الزبير، عن جابر قال: اشتكيت فدخل علي رسول الله - صلى الله عليه وسلم - وعندي سبع أخوات، فنفخ في وجهي فأفقت، فقلت: يا رسول الله أوصي لأخواتي بالثلثين، قال: \"احبس\"، فقلت الشطر، قال: \"احبس\"، ثم خرج فتركني. قال: ثم دخل علي وقال: \"يا\nجابر إني لا أراك تموت في وجعك هذا، إن الله قد أنزل، فبين الذي لأخواتك، جعل لأخواتك الثلثين\"، وكان جابر يقول: نزلت هذه الآية في {يستفتونك قل الله يفتيكم في الكلالة} ."]]);
